import type {
  Activity,
  ActivityType,
  Assessment,
  ContentBundle,
  Module,
  Resource,
} from '@repair/content-schema';
import { TIER_LABELS } from '@repair/content-schema';

// Generated by `pnpm content:build` from /content. Do not edit by hand.
import raw from './content.generated.json';

export const content = raw as unknown as ContentBundle;
export { TIER_LABELS };

const activityById = new Map(content.activities.map((a) => [a.id, a]));
const moduleBySlug = new Map(content.modules.map((m) => [m.slug, m]));

export const getModule = (slug: string): Module | undefined => moduleBySlug.get(slug);
export const getActivity = (id: string): Activity | undefined => activityById.get(id);

export function activitiesFor(moduleSlug: string, type?: ActivityType): Activity[] {
  return content.activities.filter((a) => a.module === moduleSlug && (!type || a.type === type));
}

function globalAssessment(kind: 'onboarding' | 'safety'): Assessment {
  const found = content.activities.find((a) => a.type === 'assessment' && a.kind === kind);
  if (!found || found.type !== 'assessment') throw new Error(`content bundle has no ${kind} assessment`);
  return found;
}

export const onboardingAssessment = globalAssessment('onboarding');
export const safetyScreen = globalAssessment('safety');
export const weeklyConversationId = content.checkins.weekly.conversation;

export const resources = (category?: Resource['category']) =>
  content.resources.filter((r) => !category || r.category === category);

/** Modules hidden for a user whose private safety mode is on. */
export const hiddenInSafetyMode = content.modules
  .filter((m) => m.gating.hiddenInSafetyMode)
  .map((m) => m.slug);

export const TYPE_LABELS: Record<ActivityType, string> = {
  assessment: 'Assessment',
  lesson: 'Lesson',
  exercise: 'Exercise',
  conversation: 'Conversation',
  journal: 'Journal',
  ritual: 'Ritual',
};

/**
 * Activities a user in safety mode should not be steered toward: anything
 * done together. Solo learning and private reflection stay available.
 */
export const isHiddenForSafety = (a: Activity) =>
  a.mode === 'together' || hiddenInSafetyMode.includes(a.module);
